def cycle_capital(trades, k):
    """(committed, employed) returns of one cycle."""
    total = sum(p for _, p in trades)
    return total / k, total / len(trades)

widget.solution:
def jt_composite(cohort_returns, K):
    out = []
    for t in range(K - 1, len(cohort_returns)):
        live = [cohort_returns[s][t - s] for s in range(t - K + 1, t + 1)]
        out.append(sum(live) / K)
    return out
